import{_ as i,o as a,c as n,a2 as e}from"./chunks/framework.UI9KxY5t.js";const o=JSON.parse('{"title":"Nginx 编译安装与静态站点配置","description":"从源码编译安装 Nginx，整理常用启停命令，并配好一个前端静态站点。","frontmatter":{"title":"Nginx 编译安装与静态站点配置","description":"从源码编译安装 Nginx，整理常用启停命令，并配好一个前端静态站点。","date":"2026-11-11T00:00:00.000Z","category":"工善利器","subCategory":"服务器运维","tags":["Linux","Nginx","运维"],"author":"闲生"},"headers":[],"relativePath":"posts/tools/server/nginx.md","filePath":"posts/tools/server/nginx.md"}'),l={name:"posts/tools/server/nginx.md"};function p(t,s,h,k,d,r){return a(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="nginx-编译安装与静态站点配置" tabindex="-1">Nginx 编译安装与静态站点配置 <a class="header-anchor" href="#nginx-编译安装与静态站点配置" aria-label="Permalink to &quot;Nginx 编译安装与静态站点配置&quot;">​</a></h1><p>用包管理器装 Nginx 最省事，但有些环境里需要自己指定编译参数、模块和安装路径。这篇记录一次源码编译安装的完整流程，以及装完之后最基本的配置。</p><h2 id="一、下载安装包" tabindex="-1">一、下载安装包 <a class="header-anchor" href="#一、下载安装包" aria-label="Permalink to &quot;一、下载安装包&quot;">​</a></h2><p>到 <a href="https://nginx.org/en/download.html" target="_blank" rel="noreferrer">Nginx 官方下载页</a> 选择需要的版本，下载 <code>tar.gz</code> 源码包。</p><p><img src="https://pic.imgdb.cn/item/661369f168eb9357137d271d.png" alt="Nginx 下载页"></p><h2 id="二、解压与编译安装" tabindex="-1">二、解压与编译安装 <a class="header-anchor" href="#二、解压与编译安装" aria-label="Permalink to &quot;二、解压与编译安装&quot;">​</a></h2><p>先建好安装目录，再安装编译依赖：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 创建安装目录</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">mkdir</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -p</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /usr/local/nginx</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 下载 Nginx 所需依赖</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">yum</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> install</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -y</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> gcc-c++</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> zlib</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> zlib-devel</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> openssl</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> openssl-devel</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> pcre</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> pcre-devel</span></span></code></pre></div><p>把下载好的源码包放进 <code>/usr/local/nginx</code>，然后解压、编译：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 进入目录并解压</span></span>
<span class="line"><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">cd</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /usr/local/nginx</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">tar</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -zxvf</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> nginx-1.24.0.tar.gz</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 进入源码目录</span></span>
<span class="line"><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">cd</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> nginx-1.24.0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 配置，--prefix 指定安装路径</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">./configure</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> --prefix=/usr/local/nginx</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 编译并安装</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">make</span><span style="--shiki-light:#999999;--shiki-dark:#666666;"> &amp;&amp;</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> make</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> install</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 查看安装位置</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">whereis</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> nginx</span></span></code></pre></div><p><code>--prefix</code> 决定了最终的目录结构：可执行文件在 <code>sbin/</code>，配置在 <code>conf/</code>，静态文件默认放在 <code>html/</code>。安装完成后访问服务器 IP，能看到默认欢迎页就说明成功了。</p><h2 id="三、启停命令" tabindex="-1">三、启停命令 <a class="header-anchor" href="#三、启停命令" aria-label="Permalink to &quot;三、启停命令&quot;">​</a></h2><p>Nginx 的命令都在 <code>sbin</code> 目录下，先切过去再操作：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">cd</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /usr/local/nginx/sbin/</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">./nginx</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">              # 启动</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">./nginx</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -s</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> stop</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">      # 强制停止</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">./nginx</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -s</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> quit</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">      # 等待请求处理完后退出</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">./nginx</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -s</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> reload</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">    # 重新加载配置</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">./nginx</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -s</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> reopen</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">    # 重新打开日志文件</span></span></code></pre></div><p>改完配置推荐用 <code>reload</code> 而不是 <code>stop</code>，前者不会中断正在处理的连接。</p><h2 id="四、配置一个静态站点" tabindex="-1">四、配置一个静态站点 <a class="header-anchor" href="#四、配置一个静态站点" aria-label="Permalink to &quot;四、配置一个静态站点&quot;">​</a></h2><p>把前端打包产物（例如 <code>dist</code>）上传到服务器，然后在 <code>server</code> 块里指向它：</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">server</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> {</span></span>
<span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">    listen </span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;">      80</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">;</span></span>
<span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">    server_name </span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> localhost</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">    location</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> / </span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">{</span></span>
<span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">        root </span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">  /usr/local/web/dist</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">;</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">   # dist 文件目录</span></span>
<span class="line"><span style="--shiki-light:#1E754F;--shiki-dark:#4D9375;">        index </span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;"> index.html index.htm</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">        # 如果用的是 history 路由，需要开启此项</span></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;">        # try_files $uri $uri/ /index.html;</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">    }</span></span>
<span class="line"><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">}</span></span></code></pre></div><p>改完执行 <code>./nginx -s reload</code> 生效。</p><p>如果前端项目用的是 Vue Router 或 React Router 的 history 模式，一定要打开 <code>try_files</code>，否则刷新子路由会返回 404。</p><h2 id="五、小结" tabindex="-1">五、小结 <a class="header-anchor" href="#五、小结" aria-label="Permalink to &quot;五、小结&quot;">​</a></h2><p>源码安装并不复杂，关键在于依赖齐全与 <code>--prefix</code> 路径统一。配置改动后先 <code>nginx -t</code> 检查语法，再 <code>reload</code>，能避免大部分意外。</p>`,22)])])}const g=i(l,[["render",p]]);export{o as __pageData,g as default};
